class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        min_p = float("inf")
        profit = 0
        for p in prices:
            if p < min_p:
                min_p = p
            elif p - min_p > profit:
                profit = p - min_p
        return profit

reference_solution.javascript:
function maxProfit(prices) {
    let minP = Infinity, maxP = 0;
    for (const p of prices) {
        if (p < minP) minP = p;
        else if (p - minP > maxP) maxP = p - minP;
    }
    return maxP;
}
